import React, { useState, useEffect } from 'react';

interface SetupSectionProps {
  onStartQuiz: () => void;
  onBackToHome: () => void;
  onCsvInputChange: (csv: string) => void;
  questionsPerQuiz: number;
  onQuestionsPerQuizChange: (count: number) => void;
}

const SetupSection: React.FC<SetupSectionProps> = ({ 
  onStartQuiz, 
  onBackToHome, 
  onCsvInputChange,
  questionsPerQuiz,
  onQuestionsPerQuizChange
}) => {
  // Local state for input value before submitting
  const [inputQuestionCount, setInputQuestionCount] = useState<string>(questionsPerQuiz.toString());
  
  // Handle input change without immediately updating parent state
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setInputQuestionCount(value);
  };
  
  // Update parent state when button is clicked
  const handleUpdateClick = () => {
    const numValue = parseInt(inputQuestionCount, 10);
    if (!isNaN(numValue) && numValue > 0) {
      onQuestionsPerQuizChange(numValue);
    } else {
      // Reset to previous valid value if input is invalid
      setInputQuestionCount(questionsPerQuiz.toString());
    }
  };
  
  // Update local state when props change
  useEffect(() => {
    setInputQuestionCount(questionsPerQuiz.toString());
  }, [questionsPerQuiz]);

  return (
    <div id="setup-section" className="section">
      <h2>Setup Your Quiz</h2>
      <p>Paste your questions in CSV format</p>
      <div className="format-example">Format: Question,Option A,Option B,Option C,Option D,Correct Answer,Topic</div>
      
      <div className="quiz-settings">
        <div className="questions-per-quiz-control">
          <label htmlFor="setup-questions-per-quiz">Questions per quiz:</label>
          <input
            id="setup-questions-per-quiz"
            type="number"
            min="5"
            max="100"
            value={inputQuestionCount}
            onChange={handleInputChange}
            className="question-count-input"
          />
          <button
            onClick={handleUpdateClick}
            className="btn btn-small"
          >
            Update
          </button>
        </div>
      </div>
      
      <textarea 
        id="csv-input" 
        placeholder="Paste your CSV data here..."
        onChange={(e) => onCsvInputChange(e.target.value)}
      ></textarea>
      <div className="btn-group">
        <button id="start-btn" className="btn" onClick={onStartQuiz}>Start Quiz</button>
        <button id="back-to-home-btn" className="btn btn-secondary" onClick={onBackToHome}>Back to Home</button>
      </div>
    </div>
  );
};

export default SetupSection; 