import React, { useState, useEffect } from 'react';
import './styles/Style.css';
import Header from './components/Header';
import Navigation from './components/Navigation';
import HomePage from './components/HomePage';
import SetupSection from './components/SetupSection';
import Quiz from './components/Quiz';
import Results from './components/Results';
import Stats from './components/Stats';
import ConfirmationModal from './components/ConfirmationModal';
import { Question } from './types';
import { parseCSV, getPresetQuiz, fetchExplanations } from './utils/quizHelpers';

// Import quiz data files
import quizNamesData from './data/quiz-names.txt';
import quizQuestionsData from './data/quiz-questions.csv';

function App() {
  // State management
  const [activeTab, setActiveTab] = useState<string>('home');
  const [currentSection, setCurrentSection] = useState<string>('home');
  const [csvData, setCsvData] = useState<string>('');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [defaultQuestions, setDefaultQuestions] = useState<Question[]>([]);
  const [csvQuizzes, setCsvQuizzes] = useState<{id: string; title: string; questions: number; mainTopic: string}[]>([]);
  const [currentQuizId, setCurrentQuizId] = useState<string>('');
  const [explanationsMap, setExplanationsMap] = useState<Map<string, string>>(new Map());
  const [questionsPerQuiz, setQuestionsPerQuiz] = useState<number>(20);
  const [quizNames, setQuizNames] = useState<string[]>([]);
  const [quizResults, setQuizResults] = useState<{
    score: number;
    totalQuestions: number;
    bestStreak: number;
    incorrectQuestions: Question[];
    topicScores: Record<string, { correct: number; total: number }>;
    quizId?: string;
  } | null>(null);
  const [isResetModalOpen, setIsResetModalOpen] = useState<boolean>(false);

  // Helper function to shuffle array
  const shuffleArray = <T,>(array: T[]): T[] => {
    const newArray = [...array];
    for (let i = newArray.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
    }
    return newArray;
  };

  // Helper function to determine the main topic of a set of questions
  const determineMainTopic = (questions: Question[]): string => {
    if (questions.length === 0) return "Mixed";
    
    // Count occurrences of each topic
    const topicCounts: Record<string, number> = {};
    
    questions.forEach(question => {
      const topic = question.topic || "Unknown";
      topicCounts[topic] = (topicCounts[topic] || 0) + 1;
    });
    
    // Find the topic with the highest count
    let maxCount = 0;
    let mainTopic = "Mixed";
    
    for (const [topic, count] of Object.entries(topicCounts)) {
      if (count > maxCount) {
        maxCount = count;
        mainTopic = topic;
      }
    }
    
    return mainTopic;
  };

  // Fetch explanations and default questions
  useEffect(() => {
    // Fetch explanations
    fetchExplanations().then(explanations => {
      setExplanationsMap(explanations);
    }).catch(error => {
      console.error('Error loading explanations:', error);
    });
    
    // Fetch quiz names
    fetch(quizNamesData)
      .then(response => {
        if (!response.ok) {
          throw new Error('Failed to fetch quiz names file');
        }
        return response.text();
      })
      .then(text => {
        const names = text.split('\n').filter(name => name.trim() !== '');
        // Shuffle names for randomness
        setQuizNames(shuffleArray(names));
      })
      .catch(error => {
        console.error('Error fetching quiz names:', error);
        // Fallback names in case the file can't be loaded
        setQuizNames([
          'Market Maverick Challenge',
          'Financial Fundamentals Test',
          'Investment IQ Quiz',
          'Balance Sheet Brainteaser',
          'Stock Savvy Assessment'
        ]);
      });
    
    // Fetch questions
    fetch(quizQuestionsData)
      .then(response => {
        if (!response.ok) {
          throw new Error('Failed to fetch questions CSV file');
        }
        return response.text();
      })
      .then(csvText => {
        try {
          const parsedQuestions = parseCSV(csvText);
          
          // Shuffle the entire question set first
          const shuffledQuestions = shuffleArray(parsedQuestions);
          
          setDefaultQuestions(shuffledQuestions);
          
          // Generate CSV quiz options based on question count
          const quizCount = Math.ceil(shuffledQuestions.length / questionsPerQuiz);
          const quizOptions = [];
          
          for (let i = 0; i < quizCount; i++) {
            const startIndex = i * questionsPerQuiz;
            const endIndex = Math.min(startIndex + questionsPerQuiz, shuffledQuestions.length);
            const quizQuestions = shuffledQuestions.slice(startIndex, endIndex);
            const mainTopic = determineMainTopic(quizQuestions);
            
            const title = quizNames.length > 0 
              ? quizNames[(i + 10) % quizNames.length] // Start from index 10 to avoid overlap
              : `CSV Quiz ${i+1}`;
              
            quizOptions.push({
              id: `csv-quiz-${i+1}`,
              title: title,
              questions: quizQuestions.length,
              mainTopic: mainTopic
            });
          }
          
          setCsvQuizzes(quizOptions);
        } catch (error) {
          console.error('Error parsing questions CSV file:', error);
        }
      })
      .catch(error => {
        console.error('Error fetching questions CSV file:', error);
      });
  }, [questionsPerQuiz]);

  // Function to apply explanations to questions
  const applyExplanationsToQuestions = (questions: Question[]): Question[] => {
    console.log(`Attempting to match explanations for ${questions.length} questions`);
    console.log(`Available explanations: ${explanationsMap.size}`);
    
    const result = questions.map(question => {
      const questionText = question.question;
      
      // Try to find an exact match first
      let explanation = explanationsMap.get(questionText);
      
      // If no exact match, try with normalized versions
      if (!explanation) {
        const normalizedQuestion = questionText.trim()
          .toLowerCase()
          .replace(/\s+/g, ' ')      // Replace multiple spaces with single space
          .replace(/[.,?!;:()]|\s+/g, ' ')  // Remove punctuation
          .trim();
        
        // Try to find the closest matching question from explanations
        let bestMatch = '';
        let bestMatchScore = 0;
        
        explanationsMap.forEach((value, key) => {
          const normalizedKey = key.trim()
            .toLowerCase()
            .replace(/\s+/g, ' ')
            .replace(/[.,?!;:()]|\s+/g, ' ')
            .trim();
          
          // Calculate similarity score using word overlap and length similarity
          const questionWords = new Set(normalizedQuestion.split(' '));
          const keyWords = new Set(normalizedKey.split(' '));
          const commonWords = Array.from(questionWords).filter(word => keyWords.has(word));
          
          // Consider both word overlap and length similarity
          const wordOverlapScore = commonWords.length / Math.max(questionWords.size, keyWords.size);
          const lengthDiff = Math.abs(normalizedQuestion.length - normalizedKey.length);
          const lengthSimilarity = 1 - (lengthDiff / Math.max(normalizedQuestion.length, normalizedKey.length));
          
          // Combined score weighted towards word overlap
          const similarityScore = (wordOverlapScore * 0.7) + (lengthSimilarity * 0.3);
          
          if (similarityScore > bestMatchScore) {
            bestMatchScore = similarityScore;
            bestMatch = key;
          }
        });
        
        // Lower the threshold to 0.6 and use the best match if found
        if (bestMatchScore > 0.6) {
          explanation = explanationsMap.get(bestMatch);
          console.log(`Matched question "${questionText}" to explanation for "${bestMatch}" with score ${bestMatchScore}`);
        } else {
          console.log(`No good match found for question: "${questionText}". Best match score: ${bestMatchScore}`);
        }
      } else {
        console.log(`Found exact match for question: "${questionText}"`);
      }
      
      return explanation ? { ...question, explanation } : question;
    });
    
    const withExplanations = result.filter(q => q.explanation).length;
    console.log(`Successfully matched explanations for ${withExplanations}/${questions.length} questions`);
    
    return result;
  };

  // Function to shuffle answer options while maintaining correct answer
  const shuffleOptions = (questions: Question[]): Question[] => {
    return questions.map(question => {
      const correctAnswer = question.correctAnswer;
      const options = [...question.options];
      
      // Check if the correct answer is in the options
      if (!options.includes(correctAnswer)) {
        console.error(`Question "${question.question}" has correct answer "${correctAnswer}" but it's not in the options:`, options);
        // In this case, we'll just use the original options without shuffling
        return question;
      }
      
      // Shuffle options
      for (let i = options.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [options[i], options[j]] = [options[j], options[i]];
      }
      
      return {
        ...question,
        options,
        correctAnswer
      };
    });
  };

  // Handle tab changes
  const handleTabChange = (tab: string) => {
    setActiveTab(tab);
    
    if (tab === 'home') {
      setCurrentSection('home');
    } else if (tab === 'quiz' && questions.length > 0) {
      setCurrentSection('quiz');
    } else if (tab === 'stats') {
      setCurrentSection('stats');
    }
  };

  // Handle starting a preset quiz
  const handleStartPresetQuiz = (preset: string) => {
    // Check if this is a CSV quiz
    if (preset.startsWith('csv-quiz-') && defaultQuestions.length > 0) {
      const quizIndex = parseInt(preset.split('-').pop() || '1') - 1;
      const startIndex = quizIndex * questionsPerQuiz;
      const endIndex = Math.min(startIndex + questionsPerQuiz, defaultQuestions.length);
      
      // Get the slice of questions
      let selectedQuestions = defaultQuestions.slice(startIndex, endIndex);
      
      // Shuffle the questions for variety
      selectedQuestions = shuffleArray(selectedQuestions);
      
      // Get the main topic
      const mainTopic = determineMainTopic(selectedQuestions);
      
      // Apply explanations and shuffle their options
      const questionsWithExplanations = applyExplanationsToQuestions(selectedQuestions);
      const quizQuestions = shuffleOptions(questionsWithExplanations);
      
      setQuestions(quizQuestions);
      setCurrentQuizId(preset);
    } else {
      // Get preset questions
      const presetQuestions = getPresetQuiz(preset);
      
      // Shuffle the questions for variety
      const shuffledQuestions = shuffleArray(presetQuestions);
      
      const mainTopic = determineMainTopic(shuffledQuestions);
      const questionsWithExplanations = applyExplanationsToQuestions(shuffledQuestions);
      setQuestions(questionsWithExplanations);
      setCurrentQuizId(preset);
    }
    setCurrentSection('quiz');
    setActiveTab('quiz');
  };

  // Handle "Create Your Own Quiz" button
  const handleCreateOwn = () => {
    setCurrentSection('setup');
  };

  // Handle CSV input change
  const handleCsvInputChange = (csv: string) => {
    setCsvData(csv);
  };

  // Handle start quiz button from setup section
  const handleStartCustomQuiz = () => {
    try {
      const parsedQuestions = parseCSV(csvData);
      
      // Shuffle all questions first
      const shuffledQuestions = shuffleArray(parsedQuestions);
      
      // Select the required number of questions
      let selectedQuestions = shuffledQuestions;
      if (shuffledQuestions.length > questionsPerQuiz) {
        selectedQuestions = shuffledQuestions.slice(0, questionsPerQuiz);
      }
      
      // Determine main topic for this set of questions
      const mainTopic = determineMainTopic(selectedQuestions);
      
      const questionsWithExplanations = applyExplanationsToQuestions(selectedQuestions);
      // Shuffle answer options
      setQuestions(shuffleOptions(questionsWithExplanations));
      setCurrentQuizId('custom-quiz');
      setCurrentSection('quiz');
      setActiveTab('quiz');
    } catch (error) {
      alert('Error parsing CSV data: ' + (error as Error).message);
    }
  };

  // Handle back to home button
  const handleBackToHome = () => {
    setCurrentSection('home');
    setActiveTab('home');
  };

  // Handle quiz completion
  const handleQuizComplete = (results: {
    score: number;
    totalQuestions: number;
    bestStreak: number;
    incorrectQuestions: Question[];
    topicScores: Record<string, { correct: number; total: number }>;
  }) => {
    setQuizResults(results);
    setCurrentSection('results');
    setActiveTab('quiz');
    
    // Save result to localStorage with timestamp
    const resultWithTimestamp = {
      ...results,
      quizId: currentQuizId,
      timestamp: new Date().toISOString()
    };
    
    try {
      const storedResults = localStorage.getItem('quizResults');
      const quizResults = storedResults ? JSON.parse(storedResults) : [];
      quizResults.push(resultWithTimestamp);
      localStorage.setItem('quizResults', JSON.stringify(quizResults));
    } catch (error) {
      console.error('Error saving quiz results:', error);
    }
  };

  // Handle opening the reset confirmation modal
  const handleOpenResetModal = () => {
    setIsResetModalOpen(true);
  };

  // Handle confirming the reset
  const handleConfirmReset = () => {
    // Clear all localStorage data
    localStorage.removeItem('quizResults');
    localStorage.removeItem('cumulativeTopicScores');
    
    // Reset state
    setQuizResults(null);
    setQuestions([]);
    setCurrentSection('home');
    setActiveTab('home');
    
    
    // Close modal
    setIsResetModalOpen(false);
    
    // Show success message
    setTimeout(() => {
      alert('🎉 All quiz data has been reset! Starting fresh!');
    }, 300);
    window.location.reload();
  };

  // Handle cancelling the reset
  const handleCancelReset = () => {
    setIsResetModalOpen(false);
    
    // Show cancelled message
    setTimeout(() => {
      alert('😌 Phew! Your quiz data is safe.');
    }, 300);
  };

  // Render appropriate content based on current section
  const renderContent = () => {
    switch (currentSection) {
      case 'home':
        return (
          <HomePage 
            onStartQuiz={handleStartPresetQuiz}
            onCreateOwn={handleCreateOwn}
            csvQuizzes={csvQuizzes}
            questionsPerQuiz={questionsPerQuiz}
            onQuestionsPerQuizChange={setQuestionsPerQuiz}
            quizNames={quizNames}
          />
        );
      case 'setup':
        return (
          <SetupSection 
            onStartQuiz={handleStartCustomQuiz} 
            onBackToHome={handleBackToHome} 
            onCsvInputChange={handleCsvInputChange}
            questionsPerQuiz={questionsPerQuiz}
            onQuestionsPerQuizChange={setQuestionsPerQuiz}
          />
        );
      case 'quiz':
        return (
          <Quiz 
            questions={questions}
            onQuizComplete={handleQuizComplete}
          />
        );
      case 'results':
        return quizResults ? (
          <Results 
            score={quizResults.score}
            totalQuestions={quizResults.totalQuestions}
            bestStreak={quizResults.bestStreak}
            incorrectQuestions={quizResults.incorrectQuestions}
            topicScores={quizResults.topicScores}
            questions={questions}
            onRestartQuiz={handleBackToHome}
          />
        ) : null;
      case 'stats':
        return <Stats onBackToHome={handleBackToHome} />;
      default:
        return <div>Something went wrong</div>;
    }
  };

  return (
    <div className="App">
      <div className="container" style={{maxWidth: '1200px'}}>
        <div className="quiz-app">
          <Header 
            title="ACF150 MCQ Final Boss" 
            subtitle="Test your knowledge of all things topics 6-10" 
          />
          
          {(currentSection !== 'home' && currentSection !== 'setup') && (
            <Navigation activeTab={activeTab} onTabChange={handleTabChange} />
          )}
          
          <main className="content">
            {renderContent()}
          </main>
          
          <div 
            id="sneaky-reset" 
            className="sneaky-reset" 
            style={{fontSize: '6px', padding: '2px 4px', bottom: '3px', left: '3px'}} 
            onClick={handleOpenResetModal}
          >
            DO NOT PRESS
          </div>
          
          <ConfirmationModal 
            isOpen={isResetModalOpen}
            message="Are you absolutely, positively sure you want to erase all your quiz progress? This will delete all your scores and statistics forever!"
            onConfirm={handleConfirmReset}
            onCancel={handleCancelReset}
          />
        </div>
      </div>
    </div>
  );
}

export default App;
