import { Question } from '../types';
import quizExplanationsData from '../data/quiz-explanations.txt';

// Parse CSV into question objects
export const parseCSV = (csvText: string): Question[] => {
  // Split the CSV text into lines
  const lines = csvText.trim().split('\n');
  
  // Remove header row if it exists
  const dataLines = lines[0].includes('Question,') ? lines.slice(1) : lines;
  
  // Parse each line into a question object
  const questions: Question[] = dataLines.map((line, index) => {
    const parts = line.split(',');
    
    // Need at least 7 parts: question, 4 options, correct answer, topic
    if (parts.length < 7) {
      throw new Error(`Line ${index + 1} does not have enough parts: ${line}`);
    }
    
    const [question, ...rest] = parts;
    const options = rest.slice(0, 4);
    const correctAnswer = rest[4];
    const topic = rest[5];
    
    return {
      id: index + 1,
      question: question.trim(),
      options: options.map(opt => opt.trim()),
      correctAnswer: correctAnswer.trim(),
      topic: topic.trim()
    };
  });
  
  return questions;
};

