// Calculate achievement based on score percentage
export const getAchievement = (percentage: number): string => {
  if (percentage === 100) {
    return 'Perfect Score! You\'re a quiz master!';
  } else if (percentage >= 90) {
    return 'Outstanding! Nearly perfect!';
  } else if (percentage >= 80) {
    return 'Great job! You\'re well prepared!';
  } else if (percentage >= 70) {
    return 'Good work! Keep studying to improve!';
  } else if (percentage >= 60) {
    return 'Not bad! But room for improvement.';
  } else {
    return 'Keep practicing to improve your score!';
  }
};

// Function to fetch explanations from text file
export const fetchExplanations = async (): Promise<Map<string, string>> => {
  const explanationsMap = new Map<string, string>();
  
  try {
    // First try to load from TXT file
    const txtResponse = await fetch(quizExplanationsData);
    if (txtResponse.ok) {
      const txtContent = await txtResponse.text();
      const txtLines = txtContent.split('\n');
      
      for (const line of txtLines) {
        const trimmedLine = line.trim();
        if (!trimmedLine) continue;
        
        // Split on " : " to handle the current format
        const parts = trimmedLine.split(' : ');
        if (parts.length === 2) {
          const question = parts[0].trim();
          const explanation = parts[1].trim();
          if (question && explanation) {
            explanationsMap.set(question, explanation);
          }
        }
      }
      
      console.log(`Loaded ${explanationsMap.size} explanations from TXT file`);
      return explanationsMap;
    }
  } catch (error) {
    console.error('Error loading explanations from TXT file:', error);
  }
  
  // If TXT loading fails, return empty map
  return explanationsMap;
}; 