import React, { useEffect, useState } from 'react';

interface HomePageProps {
  onStartQuiz: (preset: string) => void;
  onCreateOwn: () => void;
  csvQuizzes?: {id: string; title: string; questions: number; mainTopic: string}[];
  questionsPerQuiz: number;
  onQuestionsPerQuizChange: (count: number) => void;
  quizNames?: string[];
}

interface QuizMetadata {
  id: string;
  title: string;
  questions: number;
  mainTopic: string;
}

interface CompletionCount {
  [quizId: string]: number;
}

const HomePage: React.FC<HomePageProps> = ({ 
  onStartQuiz, 
  onCreateOwn, 
  csvQuizzes = [], 
  questionsPerQuiz,
  onQuestionsPerQuizChange,
  quizNames
}) => {
  const [completedQuizzes, setCompletedQuizzes] = useState<string[]>([]);
  const [completionCounts, setCompletionCounts] = useState<CompletionCount>({});
  
  // Quiz metadata
  const baseQuizzes: QuizMetadata[] = [
    {
      id: "quiz-1",
      title: quizNames && quizNames.length > 0 ? quizNames[0 % quizNames.length] : "Financial Fundamentals",
      questions: 40,
      mainTopic: "Financial Accounting"
    },
    {
      id: "quiz-2",
      title: quizNames && quizNames.length > 0 ? quizNames[1 % quizNames.length] : "Market Analysis",
      questions: 40,
      mainTopic: "Market Analysis"
    },
    {
      id: "quiz-3",
      title: quizNames && quizNames.length > 0 ? quizNames[2 % quizNames.length] : "Investment Strategies",
      questions: 40,
      mainTopic: "Investments"
    },
    {
      id: "quiz-4",
      title: quizNames && quizNames.length > 0 ? quizNames[3 % quizNames.length] : "Economic Principles",
      questions: 40,
      mainTopic: "Economics"
    },
    {
      id: "quiz-5",
      title: quizNames && quizNames.length > 0 ? quizNames[4 % quizNames.length] : "Corporate Finance",
      questions: 40,
      mainTopic: "Corporate Finance"
    },
    {
      id: "quiz-6",
      title: quizNames && quizNames.length > 0 ? quizNames[5 % quizNames.length] : "Banking Essentials",
      questions: 40,
      mainTopic: "Banking"
    },
    {
      id: "quiz-7",
      title: quizNames && quizNames.length > 0 ? quizNames[6 % quizNames.length] : "Risk Management",
      questions: 40,
      mainTopic: "Risk Management"
    },
    {
      id: "quiz-8",
      title: quizNames && quizNames.length > 0 ? quizNames[7 % quizNames.length] : "Portfolio Theory",
      questions: 40,
      mainTopic: "Portfolio Management"
    },
    {
      id: "quiz-9",
      title: quizNames && quizNames.length > 0 ? quizNames[8 % quizNames.length] : "International Finance",
      questions: 40,
      mainTopic: "International Finance"
    },
    {
      id: "quiz-10",
      title: quizNames && quizNames.length > 0 ? quizNames[9 % quizNames.length] : "Financial Ethics",
      questions: 40,
      mainTopic: "Ethics & Regulations"
    }
  ];
  
  // Transform CSV quizzes into the full metadata format
  const csvQuizzesMetadata: QuizMetadata[] = csvQuizzes.map((quiz, index) => ({
    id: quiz.id,
    title: quizNames && quizNames.length > 0 
      ? quizNames[(index + 10) % quizNames.length] // Start from index 10 to avoid overlap with preset quizzes
      : `CSV Quiz ${index + 1}`,
    questions: quiz.questions,
    mainTopic: quiz.mainTopic
  }));
  
  // Combine the base quizzes with CSV quizzes
  const quizzes: QuizMetadata[] = csvQuizzesMetadata.length > 0 ? csvQuizzesMetadata : baseQuizzes;
  
  // Load completed quizzes from localStorage
  useEffect(() => {
    try {
      const storedResults = localStorage.getItem('quizResults');
      if (storedResults) {
        const quizResults = JSON.parse(storedResults);
        const completedIds = new Set<string>();
        const counts: CompletionCount = {};
        
        quizResults.forEach((result: any) => {
          if (result && result.quizId) {
            completedIds.add(result.quizId);
            counts[result.quizId] = (counts[result.quizId] || 0) + 1;
          }
        });
        
        setCompletedQuizzes(Array.from(completedIds));
        setCompletionCounts(counts);
      }
    } catch (error) {
      console.error('Error loading completed quizzes:', error);
    }
  }, []);
  
  // Format completion message
  const getCompletionText = (quizId: string) => {
    const count = completionCounts[quizId] || 0;
    if (count === 0) return "Not yet";
    if (count === 1) return "1 time";
    return `${count} times`;
  };
  
  // Local state for input value before submitting
  const [inputQuestionCount, setInputQuestionCount] = useState<string>(questionsPerQuiz.toString());
  
  // Handle input change without immediately updating parent state
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setInputQuestionCount(value);
  };
  
  // Update parent state when button is clicked
  const handleUpdateClick = () => {
    const numValue = parseInt(inputQuestionCount, 10);
    if (!isNaN(numValue) && numValue > 0) {
      onQuestionsPerQuizChange(numValue);
    } else {
      // Reset to previous valid value if input is invalid
      setInputQuestionCount(questionsPerQuiz.toString());
    }
  };
  
  // Update local state when props change
  useEffect(() => {
    setInputQuestionCount(questionsPerQuiz.toString());
  }, [questionsPerQuiz]);
  
  return (
    <div id="home-section" className="section">
      <div className="welcome-message">
        <p>
          PSA:
          <br />
          1. I have updated the quiz to have 120 questions that more align with our topics.
          <br />
          2. When you change the number of questions per quiz, it will affect all the quizzes and shuffle the questions.
          <br />
          3. The red button in the bottom left corner is a sneaky reset button, it will reset the statistics for the new questions.
          </p>
      </div>
      
      <div className="quiz-settings">
        <div className="questions-per-quiz-control">
          <label htmlFor="questions-per-quiz">Questions per quiz:</label>
          <input
            id="questions-per-quiz"
            type="number"
            min="5"
            max="100"
            value={inputQuestionCount}
            onChange={handleInputChange}
            className="question-count-input"
          />
          <button
            onClick={handleUpdateClick}
            className="btn btn-small"
          >
            Update
          </button>
        </div>
      </div>
      
      <h2>Choose a Preset Quiz</h2>
      <div className="preset-quizzes">
        {quizzes.map((quiz) => (
          <div key={quiz.id} className="quiz-card">
            <div className="quiz-card-header">
              {quiz.title} {completedQuizzes.includes(quiz.id) && <span className="completed-badge">✓</span>}
            </div>
            <div className="quiz-card-body">
              <div className="quiz-card-stat">
                <div className="quiz-card-stat-label">Questions</div>
                <div className="quiz-card-stat-value">{quiz.questions}</div>
              </div>
              <div className="quiz-card-stat">
                <div className="quiz-card-stat-label">Main Topic</div>
                <div className="quiz-card-stat-value">{quiz.mainTopic}</div>
              </div>
              {Object.keys(completionCounts).length > 0 && (
                <div className="quiz-card-stat">
                  <div className="quiz-card-stat-label">Completed</div>
                  <div className={`quiz-card-stat-value ${completedQuizzes.includes(quiz.id) ? 'completed-count' : 'not-completed'}`}>
                    {getCompletionText(quiz.id)}
                  </div>
                </div>
              )}
            </div>
            <div className="quiz-card-footer">
              <button 
                className="btn start-preset-btn" 
                onClick={() => onStartQuiz(quiz.id)}
              >
                Start Quiz
              </button>
            </div>
          </div>
        ))}
      </div>
      
      <div className="divider"><div className="divider-text">OR</div></div>
      <div style={{ textAlign: 'center' }}>
        <button id="create-own-btn" className="btn btn-info" onClick={onCreateOwn}>Create Your Own Quiz</button>
      </div>
    </div>
  );
};

export default HomePage; 